import{_ as i,o as a,c as o,aj as n}from"./chunks/framework.C6uXqnaX.js";const p=JSON.parse('{"title":"Orphan field in signal forms","description":"","frontmatter":{},"headers":[],"relativePath":"en/errors/NG01902.md","filePath":"en/errors/NG01902.md"}'),t={name:"en/errors/NG01902.md"};function r(s,e,d,l,h,c){return a(),o("div",null,e[0]||(e[0]=[n('<h1 id="orphan-field-in-signal-forms" tabindex="-1">Orphan field in signal forms <a class="header-anchor" href="#orphan-field-in-signal-forms" aria-label="Permalink to &quot;Orphan field in signal forms&quot;">​</a></h1><p>This error indicates that a <code>Field</code> instance is no longer connected to the current model structure. Angular signal forms throw <code>NG01902</code> when a field path that previously existed can no longer be resolved as the same property in the parent object.</p><p>A common trigger is unintentionally setting a field&#39;s value to <code>undefined</code>. In signal forms, <code>undefined</code> means &quot;field does not exist&quot;, so an existing field can become orphaned.</p><h2 id="why-this-happens" tabindex="-1">Why this happens <a class="header-anchor" href="#why-this-happens" aria-label="Permalink to &quot;Why this happens&quot;">​</a></h2><p>Signal forms keep field instances in sync with your model shape. If code still references an older field instance after the model shape changed, Angular detects the mismatch and throws this error.</p><p>This can happen when:</p><ul><li>a property is removed from the model object</li><li>a property becomes <code>undefined</code> instead of remaining present</li><li>code holds a stale field reference across structural updates</li></ul><h2 id="how-to-fix-it" tabindex="-1">How to fix it <a class="header-anchor" href="#how-to-fix-it" aria-label="Permalink to &quot;How to fix it&quot;">​</a></h2><ul><li>Avoid writing <code>undefined</code> to model fields. Use <code>null</code> or another explicit value when the field should still exist.</li><li>Keep the model shape stable while a field is in use.</li><li>Re-read fields from the current form tree after structural updates instead of reusing stale references.</li></ul><p>For model design guidance, see <a href="/en/guide/forms/signals/model-design#avoid-undefined">Avoid <code>undefined</code></a>.</p>',10)]))}const u=i(t,[["render",r]]);export{p as __pageData,u as default};
